export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  sourcePath: string;
  outputPath: string;
  url: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
  baseUrl: string;
  devServerPort: number;
}

export interface TemplateContext {
  site: {
    title: string;
    url: string;
    baseUrl: string;
  };
  page?: {
    title: string;
    date?: string;
    tags?: string[];
    content: string;
    url: string;
  };
  pages?: Page[];
  tags?: TagIndexEntry[];
  currentTag?: string;
}

export interface TagIndexEntry {
  tag: string;
  pages: Page[];
}

import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import { marked, type Token, type Tokens } from "marked";
import hljs from "highlight.js";
import type { Page, Frontmatter } from "./types.js";

function highlightExtension(): marked.MarkedExtension {
  return {
    renderer: {
      code(token: Tokens.Code): string {
        const lang = token.lang || "";
        const text = token.text;
        if (lang && hljs.getLanguage(lang)) {
          try {
            const result = hljs.highlight(text, { language: lang });
            return `<pre><code class="hljs language-${lang}">${result.value}</code></pre>\n`;
          } catch {
            // fall through
          }
        }
        try {
          const result = hljs.highlightAuto(text);
          return `<pre><code class="hljs">${result.value}</code></pre>\n`;
        } catch {
          return `<pre><code>${escapeHtml(text)}</code></pre>\n`;
        }
      },
    },
  };
}

marked.use(highlightExtension());

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function parseFrontmatter(raw: string): { frontmatter: Frontmatter; content: string } {
  const parsed = matter(raw);
  return {
    frontmatter: parsed.data as Frontmatter,
    content: parsed.content,
  };
}

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

export async function loadPage(
  filePath: string,
  sourceDir: string,
  outputDir: string,
  baseUrl: string
): Promise<Page> {
  const raw = await fs.readFile(filePath, "utf-8");
  const { frontmatter, content } = parseFrontmatter(raw);
  const html = markdownToHtml(content);

  const relPath = path.relative(sourceDir, filePath);
  const parsed = path.parse(relPath);
  const urlPath = parsed.name === "index" ? parsed.dir : path.join(parsed.dir, parsed.name);
  const normalizedUrl = "/" + urlPath.replace(/\\/g, "/").replace(/\/$/, "") + "/";

  const outPath = path.join(outputDir, parsed.dir, parsed.name + ".html");

  // Ensure draft defaults to false if missing
  if (frontmatter.draft === undefined) {
    frontmatter.draft = false;
  }

  return {
    frontmatter,
    content,
    html,
    sourcePath: filePath,
    outputPath: outPath,
    url: normalizedUrl,
  };
}

// Parse a date string to ISO format for RSS, returns undefined if invalid
export function parseDate(value: string | undefined): Date | undefined {
  if (!value) return undefined;
  const d = new Date(value);
  return isNaN(d.getTime()) ? undefined : d;
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import type { TemplateContext } from "./types.js";

export async function loadTemplates(templateDir: string): Promise<{
  layoutTemplate: Handlebars.TemplateDelegate<TemplateContext>;
  pageTemplate: Handlebars.TemplateDelegate<TemplateContext>;
  tagTemplate: Handlebars.TemplateDelegate<TemplateContext> | null;
  partials: Map<string, Handlebars.TemplateDelegate>;
}> {
  // Register a safeMarkdown (raw HTML) helper
  Handlebars.registerHelper("safeMarkdown", function (content: string) {
    return new Handlebars.SafeString(content);
  });

  // Load partials
  const partialsDir = path.join(templateDir, "partials");
  const partials = new Map<string, Handlebars.TemplateDelegate>();
  try {
    const entries = await fs.readdir(partialsDir);
    const hbsFiles = entries.filter((f) => f.endsWith(".hbs") || f.endsWith(".handlebars"));
    await Promise.all(
      hbsFiles.map(async (file) => {
        const content = await fs.readFile(path.join(partialsDir, file), "utf-8");
        const name = path.parse(file).name;
        partials.set(name, Handlebars.compile(content));
        Handlebars.registerPartial(name, content);
      })
    );
  } catch {
    // no partials dir — ok
  }

  // Load layout
  let layoutContent: string;
  try {
    layoutContent = await fs.readFile(path.join(templateDir, "layout.hbs"), "utf-8");
  } catch {
    layoutContent = await fs.readFile(path.join(templateDir, "layout.handlebars"), "utf-8");
  }
  const layoutTemplate = Handlebars.compile<TemplateContext>(layoutContent);

  // Load page
  let pageContent: string;
  try {
    pageContent = await fs.readFile(path.join(templateDir, "page.hbs"), "utf-8");
  } catch {
    pageContent = await fs.readFile(path.join(templateDir, "page.handlebars"), "utf-8");
  }
  const pageTemplate = Handlebars.compile<TemplateContext>(pageContent);

  // Load tag page (optional)
  let tagTemplate: Handlebars.TemplateDelegate<TemplateContext> | null = null;
  try {
    let tagContent: string;
    try {
      tagContent = await fs.readFile(path.join(templateDir, "tag.hbs"), "utf-8");
    } catch {
      tagContent = await fs.readFile(path.join(templateDir, "tag.handlebars"), "utf-8");
    }
    tagTemplate = Handlebars.compile<TemplateContext>(tagContent);
  } catch {
    // optional
  }

  return { layoutTemplate, pageTemplate, tagTemplate, partials };
}

export function renderPage(
  pageTemplate: Handlebars.TemplateDelegate<TemplateContext>,
  layoutTemplate: Handlebars.TemplateDelegate<TemplateContext>,
  context: TemplateContext
): string {
  const pageHtml = pageTemplate(context);
  const fullHtml = layoutTemplate({ ...context, page: { ...context.page, content: pageHtml } as TemplateContext["page"] });
  return fullHtml;
}

export function renderTagPage(
  tagTemplate: Handlebars.TemplateDelegate<TemplateContext>,
  layoutTemplate: Handlebars.TemplateDelegate<TemplateContext>,
  context: TemplateContext
): string {
  const pageHtml = tagTemplate(context);
  return layoutTemplate({ ...context, page: { ...context.page, content: pageHtml } as TemplateContext["page"] });
}

import fs from "node:fs/promises";
import path from "node:path";
import { glob } from "node:fs/promises";
import type { Page, SiteConfig, TemplateContext, TagIndexEntry } from "./types.js";
import { loadPage } from "./parser.js";
import { loadTemplates, renderPage, renderTagPage } from "./renderer.js";

export async function generateSite(config: SiteConfig): Promise<{ pages: Page[]; elapsed: number }> {
  const start = performance.now();

  await fs.mkdir(config.outputDir, { recursive: true });

  // Discover all markdown files
  const sourceFiles: string[] = [];
  for await (const entry of glob("**/*.md", { cwd: config.sourceDir })) {
    sourceFiles.push(path.join(config.sourceDir, entry));
  }

  // Parse all files in parallel (throughput optimization)
  const allPages = await Promise.all(
    sourceFiles.map((f) => loadPage(f, config.sourceDir, config.outputDir, config.baseUrl))
  );

  // Filter out drafts
  const pages = allPages.filter((p) => !p.frontmatter.draft);

  // Load templates
  const { layoutTemplate, pageTemplate, tagTemplate } = await loadTemplates(config.templateDir);

  // Build site context
  const siteCtx = {
    title: config.siteTitle,
    url: config.siteUrl,
    baseUrl: config.baseUrl,
  };

  // Build tag index
  const tagMap = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags ?? []) {
      const existing = tagMap.get(tag);
      if (existing) {
        existing.push(page);
      } else {
        tagMap.set(tag, [page]);
      }
    }
  }
  const tags: TagIndexEntry[] = Array.from(tagMap.entries()).map(([tag, tagPages]) => ({
    tag,
    pages: tagPages,
  }));

  // Render and write page files in parallel
  await Promise.all(
    pages.map(async (page) => {
      const ctx: TemplateContext = {
        site: siteCtx,
        page: {
          title: page.frontmatter.title,
          date: page.frontmatter.date,
          tags: page.frontmatter.tags,
          content: page.html,
          url: page.url,
        },
        pages,
        tags,
      };
      const html = renderPage(pageTemplate, layoutTemplate, ctx);
      await fs.mkdir(path.dirname(page.outputPath), { recursive: true });
      await fs.writeFile(page.outputPath, html, "utf-8");
    })
  );

  // Write tag index pages in parallel
  if (tagTemplate) {
    await Promise.all(
      tags.map(async (entry) => {
        const tagDir = path.join(config.outputDir, "tags", entry.tag);
        const tagOutPath = path.join(tagDir, "index.html");
        const ctx: TemplateContext = {
          site: siteCtx,
          page: {
            title: `Tag: ${entry.tag}`,
            content: "",
            url: `/tags/${entry.tag}/`,
          },
          pages,
          tags,
          currentTag: entry.tag,
        };
        const html = renderTagPage(tagTemplate, layoutTemplate, ctx);
        await fs.mkdir(tagDir, { recursive: true });
        await fs.writeFile(tagOutPath, html, "utf-8");
      })
    );
  }

  // Copy static assets from templateDir (CSS, JS, images, etc.)
  await copyStaticAssets(config.templateDir, config.outputDir);

  const elapsed = performance.now() - start;
  return { pages, elapsed };
}

async function copyStaticAssets(templateDir: string, outputDir: string): Promise<void> {
  const assetsDir = path.join(templateDir, "assets");
  try {
    await fs.access(assetsDir);
  } catch {
    return;
  }

  const destDir = path.join(outputDir, "assets");
  await fs.cp(assetsDir, destDir, { recursive: true });
}

export function injectReloadScript(html: string, port: number): string {
  const script = `<script>
(function(){
  var ws = new WebSocket('ws://localhost:${port}/__reload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') { location.reload(); }
  };
  ws.onclose = function() {
    setTimeout(function() {
      var w = new WebSocket('ws://localhost:${port}/__reload');
      w.onmessage = function(msg) {
        if (msg.data === 'reload') { location.reload(); }
      };
    }, 1000);
  };
})();
</script>`;
  return html.replace("</body>", script + "</body>");
}

import fs from "node:fs/promises";
import path from "node:path";
import { Feed } from "feed";
import type { Page, SiteConfig } from "./types.js";
import { parseDate } from "./parser.js";

export async function generateRss(config: SiteConfig, pages: Page[]): Promise<void> {
  const feed = new Feed({
    title: config.siteTitle,
    description: `${config.siteTitle} RSS feed`,
    id: config.siteUrl,
    link: config.siteUrl,
    language: "en",
    updated: new Date(),
    generator: "staticsmith",
    feedLinks: {
      rss2: `${config.siteUrl}/feed.xml`,
    },
    copyright: "",
  });

  const publishedPages = pages
    .filter((p) => parseDate(p.frontmatter.date) !== undefined)
    .sort((a, b) => {
      const da = parseDate(a.frontmatter.date)!;
      const db = parseDate(b.frontmatter.date)!;
      return db.getTime() - da.getTime();
    });

  for (const page of publishedPages) {
    feed.addItem({
      title: page.frontmatter.title,
      id: config.siteUrl + page.url,
      link: config.siteUrl + page.url,
      date: parseDate(page.frontmatter.date)!,
      description: page.html,
      content: page.html,
    });
  }

  const outPath = path.join(config.outputDir, "feed.xml");
  await fs.mkdir(path.dirname(outPath), { recursive: true });
  await fs.writeFile(outPath, feed.rss2(), "utf-8");
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import { WebSocketServer } from "ws";
import type { AddressInfo } from "node:net";

export function createDevServer(outputDir: string, port: number): http.Server {
  const mimeTypes: Record<string, string> = {
    ".html": "text/html",
    ".css": "text/css",
    ".js": "application/javascript",
    ".json": "application/json",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".svg": "image/svg+xml",
    ".xml": "application/xml",
    ".ico": "image/x-icon",
  };

  const server = http.createServer(async (req, res) => {
    let urlPath = req.url || "/";

    // Strip query string
    const qIdx = urlPath.indexOf("?");
    if (qIdx !== -1) urlPath = urlPath.slice(0, qIdx);

    if (urlPath === "/") urlPath = "/index.html";

    const filePath = path.join(outputDir, urlPath);
    try {
      const stat = await fs.stat(filePath);
      if (stat.isDirectory()) {
        const indexFile = path.join(filePath, "index.html");
        try {
          await fs.access(indexFile);
          const content = await fs.readFile(indexFile);
          res.writeHead(200, { "Content-Type": "text/html" });
          res.end(content);
          return;
        } catch {
          res.writeHead(404);
          res.end("Not Found");
          return;
        }
      }

      const ext = path.extname(filePath).toLowerCase();
      const contentType = mimeTypes[ext] || "application/octet-stream";
      const content = await fs.readFile(filePath);
      res.writeHead(200, { "Content-Type": contentType });
      res.end(content);
    } catch {
      res.writeHead(404);
      res.end("Not Found");
    }
  });

  const wss = new WebSocketServer({ server, path: "/__reload" });

  // Heartbeat to keep connections alive
  const interval = setInterval(() => {
    wss.clients.forEach((ws) => {
      if ((ws as any).isAlive === false) return ws.terminate();
      (ws as any).isAlive = false;
      ws.ping();
    });
  }, 30000);

  wss.on("connection", (ws) => {
    (ws as any).isAlive = true;
    ws.on("pong", () => {
      (ws as any).isAlive = true;
    });
  });

  wss.on("close", () => clearInterval(interval));

  return server;
}

export function broadcastReload(server: http.Server): void {
  // Access WebSocketServer attached to the http server
  const wss = (server as any)._wss as WebSocketServer | undefined;
  // Hmm, we attached the WSS to the server via the `server` option, but it's not
  // directly accessible. Let's store it differently.
}

/**
 * Create a reload broadcaster attached to the given server.
 */
export function createReloadBroadcaster(server: http.Server): {
  broadcast: () => void;
  wss: WebSocketServer;
} {
  const wss = new WebSocketServer({ noServer: true });

  server.on("upgrade", (request, socket, head) => {
    if (request.url === "/__reload") {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit("connection", ws, request);
      });
    } else {
      socket.destroy();
    }
  });

  setInterval(() => {
    wss.clients.forEach((ws) => {
      if ((ws as any).isAlive === false) return ws.terminate();
      (ws as any).isAlive = false;
      ws.ping();
    });
  }, 30000);

  wss.on("connection", (ws) => {
    (ws as any).isAlive = true;
    ws.on("pong", () => {
      (ws as any).isAlive = true;
    });
  });

  return {
    broadcast() {
      for (const client of wss.clients) {
        if (client.readyState === 1) {
          client.send("reload");
        }
      }
    },
    wss,
  };
}

import chokidar from "chokidar";
import type { SiteConfig } from "./types.js";
import { createDevServer, createReloadBroadcaster } from "./server.js";
import { generateSite, injectReloadScript } from "./generator.js";
import { generateRss } from "./rss.js";
import fs from "node:fs/promises";
import path from "node:path";

export async function watchAndServe(config: SiteConfig): Promise<void> {
  // Initial build with reload script injection
  const { pages } = await generateSite(config);
  await generateRss(config, pages);
  await injectReloadIntoOutput(config.outputDir, config.devServerPort);

  const server = createDevServer2(config.outputDir, config.devServerPort);
  const { broadcast } = createReloadBroadcaster(server);

  server.listen(config.devServerPort, () => {
    console.log(`Dev server: http://localhost:${config.devServerPort}`);
  });

  let rebuilding = false;

  const rebuild = async () => {
    if (rebuilding) return;
    rebuilding = true;
    try {
      const { pages: newPages } = await generateSite(config);
      await generateRss(config, newPages);
      await injectReloadIntoOutput(config.outputDir, config.devServerPort);
      broadcast();
      console.log("Site rebuilt");
    } catch (err) {
      console.error("Rebuild error:", err);
    } finally {
      rebuilding = false;
    }
  };

  const watcher = chokidar.watch(
    [
      path.join(config.sourceDir, "**/*.md"),
      path.join(config.templateDir, "**/*"),
    ],
    { ignoreInitial: true }
  );

  watcher.on("change", rebuild);
  watcher.on("add", rebuild);
  watcher.on("unlink", rebuild);

  process.on("SIGINT", () => {
    watcher.close();
    server.close();
    process.exit(0);
  });
}

async function injectReloadIntoOutput(outputDir: string, port: number): Promise<void> {
  const entries = await fs.readdir(outputDir, { recursive: true });
  for (const entry of entries) {
    const fullPath = path.join(outputDir, entry.toString());
    try {
      const stat = await fs.stat(fullPath);
      if (stat.isFile() && fullPath.endsWith(".html")) {
        let html = await fs.readFile(fullPath, "utf-8");
        if (!html.includes("/__reload")) {
          html = injectReloadScript(html, port);
          await fs.writeFile(fullPath, html, "utf-8");
        }
      }
    } catch {
      // skip
    }
  }
}

